  const sorted = (list) => list.every((v, i) => i === 0 || list[i - 1] <= v);
  for (let length = 0; length <= n; length++) {
    for (let i = 0; i + length <= n; i++) {
      if (sorted([...arr.slice(0, i), ...arr.slice(i + length)])) return length;
    }
