function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(1500, 2000) : int(1, 12);
  const top = large ? (rand() < 0.5 ? 1e9 : 1000) : [3, 10, 1e9][int(0, 2)];
  const shape = rand();
  let arr = Array.from({ length: n }, () => int(0, top));
  if (shape < 0.1) {
    arr.sort((a, b) => a - b);
  } else if (shape < 0.2) {
    arr.sort((a, b) => b - a);
  } else if (shape < 0.8) {
    // A sorted prefix, a jumbled middle and a sorted suffix make the two pointers do real work.
    const cutA = int(0, n);
    const cutB = int(cutA, n);
    const prefix = arr.slice(0, cutA).sort((a, b) => a - b);
    const middle = arr.slice(cutA, cutB);
    const suffix = arr.slice(cutB).sort((a, b) => a - b);
    arr = [...prefix, ...middle, ...suffix];
  }
  return [arr];
}
